public readonly struct Maybe<T>
{
    private readonly T value;
    public Maybe(T value) { this.value = value; }
    public static bool operator true(Maybe<T> m) => m.value is not null;
    public static bool operator false(Maybe<T> m) => m.value is null;
    public bool HasValue => value is not null;   // named predicate: preferred
}
